&reftitle.description;
#[\Deprecated(since: '8.4', message: 'provide a proper method callable to xml_set_*_handler() functions')] truexml_set_object XMLParserparser objectobject
Questa funzione permette l'uso del parser all'interno di un object. Tutte le funzioni di callback possono essere indicate con xml_set_element_handler e simili, e sono assunte come metodi dell'object.

&reftitle.changelog;





    &Version;
    &Description;





    8.4.0

     Questa funzione è ora deprecata;
     passare invece valori callable appropriati alle funzioni
     xml_set_


    &xml.changelog.parser-param;

  &reftitle.examples;



    Esempio di uso di xml_set_object


<?php
class CustomXMLParser
{
    private $parser;

    function __construct() 
    {
        $this->parser = xml_parser_create();

        xml_set_object($this->parser, $this);
        xml_set_element_handler($this->parser, "tag_open", "tag_close");
        xml_set_character_data_handler($this->parser, "cdata");
    }

    function parse($data) 
    {
        xml_parse($this->parser, $data);
    }

    function tag_open($parser, $tag, $attributes) 
    {
        var_dump($tag, $attributes); 
    }

    function cdata($parser, $cdata) 
    {
        var_dump($cdata);
    }

    function tag_close($parser, $tag) 
    {
        var_dump($tag);
    }
}

$xml_parser = new CustomXMLParser();
$xml_parser->parse("<A ID='hallo'>PHP</A>");
?>


    &example.outputs;


string(1) "A"
array(1) {
  ["ID"]=>
  string(5) "hallo"
}
string(3) "PHP"
string(1) "A"
